import React from 'react';
import { Link } from 'react-router-dom';
import { Instagram, Twitter, MessageCircle, ArrowRight } from 'lucide-react';
import './Footer.css';

const LINKS = {
  Conference: [
    { label: 'Home', to: '/#home' },
    { label: 'About', to: '/#about' },
    { label: 'Speakers', to: '/#speakers' },
    { label: 'Programme', to: '/#programme' },
  ],
  Resources: [
    { label: 'Register', to: '/register' },
    { label: 'FAQ', to: '/#faq' },
    { label: 'Contact Us', to: '/#contact' },
  ],
};

export default function Footer() {
  const year = new Date().getFullYear();

  const scrollTo = (id) => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <footer className="footer">
      {/* Main marquee bar */}
      <div className="footer__marquee-wrap">
        <div className="footer__marquee">
          {Array(6).fill('BUILD & SCALE 2026 · BUILDING MEN WHO BUILD SOCIETY ·').map((t, i) => (
            <span key={i} className="footer__marquee-text">{t}&nbsp;</span>
          ))}
        </div>
      </div>

      <div className="footer__main container">
        {/* Brand block */}
        <div className="footer__brand">
          <div className="footer__logo">
            <div className="footer__logo-mark">B&S</div>
            <div className="footer__logo-text">
              <span className="footer__logo-title">Build & Scale</span>
              <span className="footer__logo-year">2026</span>
            </div>
          </div>
          <p className="footer__tagline">
            Building Men Who Build Society.
            <br />
            Friday, 30th May 2026 · Enugu.
          </p>
          <div className="footer__socials">
            <a href="#" className="footer__social" aria-label="Instagram"><Instagram size={17} /></a>
            <a href="#" className="footer__social" aria-label="Twitter"><Twitter size={17} /></a>
            <a href="#" className="footer__social" aria-label="WhatsApp"><MessageCircle size={17} /></a>
          </div>
        </div>

        {/* Link columns */}
        {Object.entries(LINKS).map(([group, links]) => (
          <div key={group} className="footer__col">
            <h5 className="footer__col-heading">{group}</h5>
            <ul className="footer__col-links">
              {links.map((l) => (
                <li key={l.label}>
                  <Link
                    to={l.to}
                    className="footer__link"
                    onClick={(e) => {
                      if (l.to.startsWith('/#')) {
                        e.preventDefault();
                        scrollTo(l.to.replace('/#', ''));
                      }
                    }}
                  >
                    {l.label}
                  </Link>
                </li>
              ))}
            </ul>
          </div>
        ))}

        {/* CTA block */}
        <div className="footer__cta-block">
          <p className="footer__cta-label">Ready to build?</p>
          <h4 className="footer__cta-title">Secure your seat before spaces run out.</h4>
          <Link to="/register" className="footer__cta-btn">
            <span>Register Now</span>
            <ArrowRight size={15} />
          </Link>
        </div>
      </div>

      {/* Bottom bar */}
      <div className="footer__bottom">
        <div className="container footer__bottom-inner">
          <p className="footer__copy">
            © {year} Build & Scale 2026. Organised by Godfrey Okoye University Student Team.
          </p>
          <p className="footer__credit">
            Convened by Azua Suurshater Stephen · 400 Level · GO University
          </p>
        </div>
      </div>
    </footer>
  );
}
